// Generated by tools/build.mjs. Caches the app so it works offline.
const VERSION = 'mahjong-bc857be6e276';
const FILES = ["./","./index.html","./trainer.html","./manifest.webmanifest","./sw.js","./icon-180.png","./icon-192.png","./icon-512.png"];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(VERSION).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

// Pages: try the network first so updates show up, fall back to the cache offline.
// Everything else: cache first.
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  if (e.request.mode === 'navigate') {
    // Cache each page under its own address (the game is './', the trainer './trainer.html').
    const url = new URL(e.request.url);
    const key = url.pathname.endsWith('/') ? './' : './' + url.pathname.split('/').pop();
    e.respondWith(fetch(e.request)
      .then(res => { if (res.ok) { const copy = res.clone(); caches.open(VERSION).then(c => c.put(key, copy)); } return res; })
      .catch(() => caches.match(key).then(hit => hit || caches.match('./'))));
    return;
  }
  e.respondWith(caches.match(e.request, { ignoreSearch: true }).then(hit => hit || fetch(e.request)));
});
